import {flightControls,FLIGHT_KEYS} from './controls.js';
import {createEffectPainter,renderProjectile,renderVisual,renderBeam,renderHullDetail,stepVisuals} from './effects.js';
import {frame,onStart,onFixedUpdate,onRender,setFixedRate} from 'starhermit:engine';
import {Color,PerspectiveCamera,renderer,scene} from 'starhermit:scene';
